import {projects} from './all-projects.js';
import {profile,services} from './data.js';
const main=document.querySelector('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=s=>'/assets/'+s.split('/').pop();
const image=(p,cls='')=>`<img class="${cls}" src="${asset(p.image)}" alt="${esc(p.alt||p.name||p.caption)}" loading="lazy" decoding="async">`;
const card=p=>`<a class="card" href="/work/${p.slug}/"><div class="visual">${image(p)}<span class="arrow" aria-hidden="true">↗</span></div><div class="card-info"><h3>${esc(p.name)}</h3><span class="tag">${esc(p.type)}</span></div></a>`;
const serviceList=()=>`<div class="services">${services.map((s,i)=>`<details><summary><span><small class="eyebrow">0${i+1} &nbsp;</small> ${esc(s.name)}</span></summary><p>${esc(s.description)}</p><ul>${s.outputs.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><a class="round-link" href="/contact/">Discuss your project <b>↗</b></a></details>`).join('')}</div>`;
const intro=()=>`<section class="intro"><p class="eyebrow">A LITTLE ABOUT US</p><div><h2>Good design gets noticed.<br><i>Thoughtful design connects.</i></h2><p>We are Zayon Creative Studios. We bring brand identity, packaging, digital experiences and everyday communication together, so your business looks and feels like itself wherever people find it.</p><a class="round-link" href="/about/">Meet the studio <b>↗</b></a>${serviceList()}</div></section>`;
function home(){main.innerHTML=`<section class="hero shell"><div class="hero-top"><span class="eyebrow">INDEPENDENT CREATIVE STUDIO</span><span class="eyebrow available">OPEN TO COLLABORATIONS</span></div><h1>Made to<br><i>stand apart.</i></h1><div class="hero-bottom"><p>Distinctive identities. Considered packaging.<br>Websites that bring it all together.<br>We turn your ambition into a brand people feel.</p><a href="/contact/" class="round-link">Start a project <b>↗</b></a></div>${categoryButtons()}</section><div class="shell">${intro()}</div>`}
// Work: a category picker (/work/) that enters each category (/work/?category=id) with a 3D transition.
const categories=[{id:'identity',name:'Brand identity',picks:['antelope-constructions','foot-impact','savory-studios']},{id:'packaging',name:'Packaging',picks:['fury-energy-drink','cool-harvest-farms','elios-yoghurt']},{id:'social',name:'Social media',picks:['glorious-praise','kbec','d-adeola-shops']},{id:'website',name:'Websites',picks:[]}];
const websites=[{name:'ScholarEdu',url:'https://scholaredu.org/',type:'Online tutoring',blurb:'Personalised online tutoring for children aged 4–17, across UK, US and Canadian curricula.',embed:true},{name:'NonStop Travels',url:'https://nonstoptravels.co/',type:'Travel and relocation',blurb:'Personal guidance for study abroad, work abroad, visas, holidays, flights and international relocation.',embed:false},{name:'Wingate Exotic Hotel',url:'https://wingateexotic.com/',type:'Hospitality',blurb:'A hotel website presenting the rooms, amenities and guest experience.',embed:true},{name:'ResideNG',url:'https://resideng.com/',type:'Real estate',blurb:'Verified homes for rent and property for sale across Nigeria, dealing directly with landlords.',embed:true}];
const domainOf=u=>new URL(u).hostname.replace(/^www\./,'');
// Live preview where the site allows embedding; a designed card where it does not. Each opens the live site in a new tab.
const siteCard=w=>`<article class="site-card"><a class="site-frame" href="${w.url}" target="_blank" rel="noopener" aria-label="Open ${esc(w.name)} in a new tab"><span class="site-bar"><i></i><i></i><i></i><em>${esc(domainOf(w.url))}</em></span><span class="site-view">${w.embed?`<iframe src="${w.url}" title="${esc(w.name)} live preview" loading="lazy" tabindex="-1" scrolling="no" sandbox="allow-scripts allow-same-origin"></iframe>`:`<span class="site-fallback"><b>${esc(w.name)}</b><small>${esc(domainOf(w.url))}</small></span>`}</span></a><div class="card-info"><h3>${esc(w.name)}</h3><span class="tag">${esc(w.type)}</span></div><p class="site-blurb">${esc(w.blurb)}</p><a class="site-visit" href="${w.url}" target="_blank" rel="noopener">Visit live site ↗</a></article>`;
const fitPreviews=root=>root.querySelectorAll('.site-view').forEach(v=>v.style.setProperty('--s',v.clientWidth/1440));
const inCategory=id=>id==='all'?projects:projects.filter(p=>p.category===id);
const calm=()=>document.body.classList.contains('quiet');
const coverOf=slug=>asset(projects.find(p=>p.slug===slug)?.image||'');
const countLabel=id=>{if(id==='website')return websites.length?`${websites.length} live sites`:'Coming soon';const rows=inCategory(id);if(!rows.length)return 'Coming soon';return id==='social'?`${pinsFor(rows).length} designs`:`${rows.length} projects`};
const webMock=()=>`<div class="web-mock" aria-hidden="true"><span class="bar"><i></i><i></i><i></i></span><span class="hero-block"></span><span class="row"><i></i><i></i><i></i></span></div>`;
function categoryButtons(){return `<div class="cat-buttons" role="navigation" aria-label="Explore our work">${categories.map((c,i)=>`<a href="/work/?category=${c.id}"><small>0${i+1}</small><span>${esc(c.name)}</span><b aria-hidden="true">↗</b></a>`).join('')}</div>`}
let onResize=null;addEventListener('resize',()=>onResize&&onResize());
addEventListener('popstate',()=>{if(/^\/work\/?$/.test(location.pathname))work()});
const go=url=>{history.pushState({},'',url);scrollTo(0,0);work()};
function work(){const id=new URLSearchParams(location.search).get('category');if(categories.some(c=>c.id===id))workCategory(id);else workHub()}
const hubCard=(c,i)=>`<a class="hub-card" href="/work/?category=${c.id}" data-cat="${c.id}"><div class="hub-face"><div class="hub-media">${c.picks.length?c.picks.slice(0,1).map((s,j)=>`<img class="layer l${j}" src="${coverOf(s)}" alt="" decoding="async">`).join(''):webMock()}</div><div class="hub-info"><span class="eyebrow">0${i+1}</span><h2>${esc(c.name)}</h2><p>${countLabel(c.id)}</p></div><span class="hub-go" aria-hidden="true">↗</span></div></a>`;
function workHub(){onResize=null;document.title='Work | Zayon Studios';main.innerHTML=`<div class="shell work-hub"><section class="hub-head"><span class="eyebrow">THE PORTFOLIO</span><h1>Choose a <i>category.</i></h1><p>Step into the work you want to see.</p></section><div class="hub-grid">${categories.map(hubCard).join('')}</div></div>`;
const cards=[...main.querySelectorAll('.hub-card')];
if(!calm())cards.forEach((c,i)=>c.animate([{transform:'perspective(1400px) rotateX(-35deg) translate3d(0,70px,-260px)',opacity:0},{transform:'perspective(1400px) rotateX(0deg) translate3d(0,0,0)',opacity:1}],{duration:900,delay:120+i*90,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'}));
if(matchMedia('(hover:hover) and (pointer:fine)').matches)cards.forEach(card=>{const face=card.querySelector('.hub-face');card.onpointermove=e=>{if(calm())return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;face.style.transform=`rotateY(${x*18}deg) rotateX(${-y*18}deg) translateZ(24px)`};card.onpointerleave=()=>{face.style.transform=''}});
main.querySelectorAll('[data-cat]').forEach(a=>a.onclick=e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button)return;e.preventDefault();enterCategory(a.dataset.cat,a.classList.contains('hub-card')?a:null)})}
let entering=false;
async function enterCategory(id,card){if(entering)return;const url=`/work/?category=${id}`;if(calm()){go(url);return}entering=true;
const cards=[...main.querySelectorAll('.hub-card')],k=card?cards.indexOf(card):-1,P='perspective(1400px) ';
const anims=cards.map((c,i)=>{if(c===card){const r=c.getBoundingClientRect(),dx=innerWidth/2-(r.left+r.width/2),dy=innerHeight/2-(r.top+r.height/2);c.style.position='relative';c.style.zIndex=5;c.querySelector('.hub-face').style.transform='';return c.animate([{transform:P+'translate3d(0,0,0) rotateY(0deg)',opacity:1},{transform:P+`translate3d(${dx}px,${dy}px,420px) rotateY(0deg)`,opacity:1,offset:.55},{transform:P+`translate3d(${dx}px,${dy}px,1000px) rotateY(0deg)`,opacity:0}],{duration:1050,easing:'cubic-bezier(.65,0,.35,1)',fill:'forwards'})}const d=k<0?0:Math.sign(i-k);return c.animate([{transform:P+'translate3d(0,0,0) rotateY(0deg)',opacity:1},{transform:P+`translate3d(${d*160}px,0,-650px) rotateY(${d*75}deg)`,opacity:0}],{duration:750,easing:'cubic-bezier(.5,0,.75,0)',fill:'forwards'})});
anims.push(main.querySelector('.hub-head').animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-40px)'}],{duration:450,easing:'ease-in',fill:'forwards'}));
await Promise.all(anims.map(a=>a.finished.catch(()=>{})));entering=false;go(url)}
function rise(els,base=0){if(calm()||!els.length)return;[...els].sort((a,b)=>a.getBoundingClientRect().top-b.getBoundingClientRect().top||a.getBoundingClientRect().left-b.getBoundingClientRect().left).forEach((el,i)=>el.animate([{transform:'perspective(1200px) rotateX(-65deg) translate3d(0,90px,-320px)',opacity:0},{transform:'perspective(1200px) rotateX(0deg) translate3d(0,0,0)',opacity:1}],{duration:850,delay:base+Math.min(i,16)*55,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'}))}
const soonBlock=()=>`<div class="soon-card">${webMock()}<div><span class="eyebrow">IN PRODUCTION</span><h3>Website case studies are on their way.</h3><p>We design and build responsive websites, from focused landing pages to complete business sites. Selected projects will appear here soon.</p><a class="round-link" href="/contact/">Start a website project <b>↗</b></a></div></div>`;
function workCategory(id){const cat=categories.find(c=>c.id===id);document.title=`${cat.name} | Zayon Studios`;
main.innerHTML=`<div class="shell archive cat-view"><section class="cat-head"><a href="/work/" class="eyebrow cat-back">← ALL CATEGORIES</a><h1>${esc(cat.name)}</h1></section><div class="filters" aria-label="Switch category">${categories.map(c=>`<button data-switch="${c.id}" aria-pressed="${c.id===cat.id}">${esc(c.name)}</button>`).join('')}</div><div class="section-head"><h2 id="count" role="status"></h2><span class="eyebrow">ZAYON STUDIOS</span></div><div id="projects"></div><button class="load" id="more">Show more projects ↓</button></div>`;
const rows=inCategory(cat.id),list=main.querySelector('#projects'),more=main.querySelector('#more'),step=cat.id==='social'?24:12;let limit=step,columns=0;
function render(){let label=`${rows.length} PROJECTS`,total=rows.length;
if(cat.id==='website'&&websites.length){list.className='sites';list.innerHTML=websites.map(siteCard).join('');label=`${websites.length} WEBSITES`;total=websites.length;fitPreviews(list)}
else if(!rows.length){list.className='soon';list.innerHTML=soonBlock();label='COMING SOON';total=0}
else if(cat.id==='social'){const items=pinsFor(rows);total=items.length;label+=` · ${items.length} DESIGNS`;list.className='masonry';columns=masonry(list,items.slice(0,limit))}
else{list.className='grid';list.innerHTML=rows.slice(0,limit).map(card).join('')}
main.querySelector('#count').textContent=label;more.hidden=limit>=total;list.querySelectorAll('[data-flyer]').forEach(b=>b.onclick=()=>openFlyer(b.dataset.flyer,+b.dataset.i))}
render();onResize=()=>{if(cat.id==='social'&&columnCount(list)!==columns)render();if(cat.id==='website')fitPreviews(list)};
more.onclick=()=>{const seen=new Set([...list.querySelectorAll('img')].map(i=>i.getAttribute('src')));limit+=step;render();rise([...list.children].flatMap(c=>c.classList.contains('masonry-col')?[...c.children]:[c]).filter(el=>!seen.has(el.querySelector('img')?.getAttribute('src'))))};
main.querySelector('.cat-back').onclick=e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button)return;e.preventDefault();leave('/work/')};
main.querySelectorAll('[data-switch]').forEach(b=>b.onclick=()=>{if(b.dataset.switch!==cat.id)leave(`/work/?category=${b.dataset.switch}`)});
if(!calm()){main.querySelector('.cat-head h1').animate([{transform:'perspective(1000px) rotateX(75deg) translate3d(0,40px,-220px)',opacity:0},{transform:'perspective(1000px) rotateX(0deg) translate3d(0,0,0)',opacity:1}],{duration:900,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'});main.querySelectorAll('.cat-back,.filters,.section-head').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(16px)'},{opacity:1,transform:'none'}],{duration:600,delay:150+i*80,fill:'backwards'}));rise([...list.children].flatMap(c=>c.classList.contains('masonry-col')?[...c.children]:[c]),280)}}
async function leave(url){if(entering)return;if(calm()){go(url);return}entering=true;const list=main.querySelector('#projects');await Promise.all([list.animate([{transform:'perspective(1400px) rotateY(0deg) translateZ(0)',opacity:1},{transform:'perspective(1400px) rotateY(-28deg) translateZ(-420px)',opacity:0}],{duration:520,easing:'cubic-bezier(.5,0,.75,0)',fill:'forwards'}).finished,main.querySelector('.cat-head').animate([{opacity:1},{opacity:0,transform:'translateY(-30px)'}],{duration:400,fill:'forwards'}).finished].map(f=>f.catch(()=>{})));entering=false;go(url)}
// Former Graphic design flyers open full size here, with arrows through the rest of their series.
function openFlyer(slug,i){const p=projects.find(x=>x.slug===slug);if(!p)return;const d=document.querySelector('dialog'),imgs=p.gallery.map(g=>g.image);let k=i;
let nav=d.querySelector('.lb-nav');if(!nav){nav=document.createElement('div');nav.className='lb-nav';nav.innerHTML='<button type="button" class="lb-prev" aria-label="Previous design">←</button><span class="lb-cap" aria-live="polite"></span><button type="button" class="lb-next" aria-label="Next design">→</button>';d.append(nav);d.addEventListener('close',()=>{nav.hidden=true})}
const show=()=>{const im=d.querySelector('img');im.src=asset(imgs[k]);im.alt=imgs.length>1?`${p.name}, design ${k+1} of ${imgs.length}`:p.name;nav.querySelector('.lb-cap').textContent=imgs.length>1?`${p.name} · ${k+1} / ${imgs.length}`:p.name;nav.querySelectorAll('button').forEach(b=>b.hidden=imgs.length<2)};
nav.querySelector('.lb-prev').onclick=()=>{k=(k-1+imgs.length)%imgs.length;show()};nav.querySelector('.lb-next').onclick=()=>{k=(k+1)%imgs.length;show()};
d.onkeydown=e=>{if(nav.hidden||imgs.length<2)return;if(e.key==='ArrowLeft')nav.querySelector('.lb-prev').click();if(e.key==='ArrowRight')nav.querySelector('.lb-next').click()};
nav.hidden=false;show();d.showModal()}
// Social media view: Pinterest-style masonry. Each image keeps its own shape, and items fill the shortest column so the reading order stays left to right.
// Former Graphic design projects show every image in their gallery and open in the viewer; the other projects show their cover and open their page.
const sizes={};projects.forEach(p=>(p.gallery||[]).forEach(g=>{if(g.width&&g.height)sizes[g.image.split('/').pop()]=[g.width,g.height]}));
const sizeOf=image=>sizes[image.split('/').pop()]||[1,1];
const columnCount=el=>{const w=el.clientWidth||innerWidth;return w>=1100?4:w>=720?3:2};
const pinsFor=rows=>rows.flatMap(p=>(p.formerly==='graphic'&&p.gallery?.length?p.gallery.map(g=>g.image):[p.image]).map((image,i,all)=>({p,image,i,of:all.length})));
const pin=({p,image,i,of})=>{const [w,h]=sizeOf(image),alt=of>1?`${p.name}, design ${i+1} of ${of}`:p.name,flyer=p.formerly==='graphic';const inner=`<div class="visual"><img src="${asset(image)}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy" decoding="async"><span class="arrow" aria-hidden="true">${flyer?'⤢':'↗'}</span></div><h3>${esc(p.name)}</h3>`;return flyer?`<button type="button" class="card pin" data-flyer="${p.slug}" data-i="${i}" aria-label="View ${esc(alt)} full size">${inner}</button>`:`<a class="card pin" href="/work/${p.slug}/">${inner}</a>`};
function masonry(el,items){const n=columnCount(el);const cols=Array.from({length:n},()=>({h:0,items:[]}));items.forEach(item=>{const [w,h]=sizeOf(item.image);const c=cols.reduce((a,b)=>b.h<a.h-0.01?b:a);c.items.push(item);c.h+=h/w+0.15});el.innerHTML=cols.map(c=>`<div class="masonry-col">${c.items.map(pin).join('')}</div>`).join('');return n}
function about(){main.innerHTML=`<div class="shell"><section class="page-head"><span class="eyebrow">MEET ZAYON</span><h1>A small studio.<br><i>A clear point of view.</i></h1></section><section class="intro"><div><img class="portrait" src="/assets/isaac-portrait-640.webp" alt="Odusina Isaac, founder and creative director"><p class="eyebrow">ODUSINA ISAAC IMOLEAYO<br>FOUNDER & CREATIVE DIRECTOR</p></div><div><h2>Built on curiosity.<br>Driven by <i>purpose.</i></h2><p>Zayon Creative Studios is led by Odusina Isaac Imoleayo. Based in Abuja, Nigeria, we work with businesses and organisations remotely around the world.</p><p>Our work brings together visual identity, packaging, websites and communication design. We look at how each piece fits the bigger picture, from the first impression to the materials your team uses every day.</p><p>We start by understanding what you do, who you serve and where you want to go. Then we translate that understanding into a visual direction you can build on.</p>${serviceList()}</div></section><section class="intro"><p class="eyebrow">HOW WE WORK</p><div>${[['Understand','We discuss your business, audience, goals and the challenge the design needs to solve.'],['Create','We explore a clear visual direction, then develop the agreed concepts with your feedback.'],['Bring it together','We refine the details and prepare the agreed assets for the places your brand needs to show up.']].map(([h,p],i)=>`<div class="section-head"><div><span class="eyebrow">0${i+1}</span><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div></section></div>`}
function project(slug){const p=projects.find(x=>x.slug===slug);if(!p){main.innerHTML='<section class="shell page-head"><h1>Project not found.</h1><a href="/work/">Explore all work ↗</a></section>';return}document.title=p.name+' | Zayon Studios';const next=projects[(projects.indexOf(p)+1)%projects.length];main.innerHTML=`<article class="shell"><section class="page-head project-head"><a href="/work/" class="eyebrow">← ALL WORK</a><h1>${esc(p.name)}</h1><span class="tag">${esc(p.type)}</span><p>${esc(p.intro||p.descriptor)}</p></section>${image(p,'project-hero')}<div class="project-story">${(p.story||[['The project',p.intro]]).map(([h,t])=>`<section><h2>${esc(h)}</h2><p>${esc(t)}</p></section>`).join('')}</div><div class="gallery">${p.gallery.map((g,i)=>`<figure><button data-image="${i}" aria-label="Enlarge ${esc(g.alt||g.caption||p.name)}">${image(g)}</button><figcaption>${esc(g.caption||g.alt||'')}</figcaption></figure>`).join('')}</div><section class="next"><span class="eyebrow">NEXT PROJECT</span><a href="/work/${next.slug}/">${esc(next.name)} ↗</a></section></article>`;main.querySelector('.project-hero').loading='eager';main.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const g=p.gallery[+b.dataset.image],d=document.querySelector('dialog');d.querySelector('img').src=asset(g.image);d.querySelector('img').alt=g.alt||g.caption||p.name;d.showModal()})}
function contact(){main.innerHTML=`<div class="shell"><section class="page-head"><span class="eyebrow">LET'S MAKE SOMETHING GOOD</span><h1>Your next chapter<br><i>starts here.</i></h1><p>Tell us what you're building. A new brand, a fresh direction or something you haven't quite put into words yet.</p></section><section class="contact-layout"><div class="contact-links"><span class="eyebrow">SAY HELLO</span><a href="mailto:${profile.email}">${profile.email} ↗</a><a href="${profile.whatsapp}" target="_blank" rel="noopener">Chat on WhatsApp ↗</a><a href="tel:${profile.telephone}">${profile.phone}</a><p>Abuja, Nigeria<br>Open to remote work worldwide.</p></div><form id="brief"><div class="form-row"><label>Your name *<input name="name" required autocomplete="name" maxlength="120"></label><label>Email address *<input name="email" type="email" required autocomplete="email" maxlength="254"></label></div><label>Business / organisation<input name="business" maxlength="160" autocomplete="organization"></label><div class="form-row"><label>What do you need?<select name="service">${services.map(s=>`<option>${esc(s.name)}</option>`).join('')}<option>Multiple services</option></select></label><label>Budget & currency<input name="budget" placeholder="Your estimated budget" maxlength="100"></label></div><label>Tell us about your project *<textarea name="details" rows="4" required maxlength="4000" placeholder="Your goals, audience and ideal timeline..."></textarea></label><button class="primary">Prepare my enquiry ↗</button><p class="hint">Prepare your brief, then choose email or WhatsApp to review and send it.</p><div id="brief-result" role="status"></div></form></section></div>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const text=`Hello Zayon Studios,\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nBusiness: ${f.get('business')}\nService: ${f.get('service')}\nBudget: ${f.get('budget')}\n\n${f.get('details')}`;document.querySelector('#brief-result').innerHTML=`<p>Your enquiry is ready. Choose where to open your draft.</p><a href="mailto:${profile.email}?subject=Project%20enquiry&body=${encodeURIComponent(text)}">Open email draft ↗</a><a href="${profile.whatsapp}?text=${encodeURIComponent(text)}" target="_blank" rel="noopener">Open WhatsApp draft ↗</a><p class="hint">Nothing has been sent yet.</p>`}}
const path=location.pathname.split('/').filter(Boolean);if(path[0]==='work'&&path[1])project(path[1]);else if(path[0]==='work')work();else if(path[0]==='about')about();else if(path[0]==='contact')contact();else home();
document.querySelectorAll('header nav a').forEach(a=>{if(location.pathname===new URL(a.href).pathname)a.setAttribute('aria-current','page')});
const motion=document.querySelector('#motion');let quiet=matchMedia('(prefers-reduced-motion:reduce)').matches;try{quiet=localStorage.getItem('zayon-quiet')==='true'||quiet}catch{}function update(){document.body.classList.toggle('quiet',quiet);motion.textContent=quiet?'◉ MOTION OFF':'◉ MOTION ON';motion.setAttribute('aria-pressed',!quiet)}update();motion.onclick=()=>{quiet=!quiet;update();try{localStorage.setItem('zayon-quiet',quiet)}catch{}};const dialog=document.querySelector('dialog');dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};
